package com.vendorportal;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.security.core.context.SecurityContextHolder;
import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.*;

@RestController
@RequestMapping("/api")
class ApiController {
  private final JdbcTemplate db;
  private final PasswordEncoder encoder;
  ApiController(JdbcTemplate db, PasswordEncoder encoder) { this.db=db; this.encoder=encoder; }
  record Login(@NotBlank String username, @NotBlank String password) {}
  record UserInput(@NotBlank @Size(max=80) @Pattern(regexp="^[A-Za-z0-9._-]+$") String username, @NotBlank @Size(min=12,max=72) String password, @NotBlank @Pattern(regexp="ADMIN|PURCHASE_MANAGER|INVENTORY_MANAGER|VENDOR") String role, Long vendorId) {}
  record VendorInput(@NotBlank @Size(max=160) String name, @NotBlank @Email String email, @Pattern(regexp="^$|^[+0-9() .-]{7,32}$") String phone, @Size(max=500) String address) {}
  record ProductInput(@NotBlank @Size(max=64) String sku, @NotBlank @Size(max=160) String name, String description, @NotBlank String category, @NotNull @DecimalMin("0.00") BigDecimal unitPrice, @Min(0) int stockQuantity, @Min(0) int reorderThreshold) {}
  record LineInput(@NotNull Long productId, @Min(1) int quantity) {}
  record OrderInput(@NotNull Long vendorId, @NotEmpty List<@Valid LineInput> items, @Size(max=2000) String notes) {}
  record Adjustment(@Min(0) int quantity, @NotBlank String note) {}
  private String currentUser() { return SecurityContextHolder.getContext().getAuthentication().getName(); }
  private String currentRole() { return db.queryForObject("SELECT role FROM app_users WHERE username=?",String.class,currentUser()); }
  private Long currentVendorId() { return db.queryForObject("SELECT vendor_id FROM app_users WHERE username=?",Long.class,currentUser()); }
  private Long currentId() { return db.queryForObject("SELECT id FROM app_users WHERE username=?", Long.class, currentUser()); }
  private Map<String,Object> one(String sql,Object... args) { return db.queryForMap(sql,args); }
  private List<Map<String,Object>> many(String sql,Object... args) { return db.queryForList(sql,args); }
  private long insertId(String sql,Object... args) {
    KeyHolder keys=new GeneratedKeyHolder();
    db.update(connection->{PreparedStatement statement=connection.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int n=0;n<args.length;n++)statement.setObject(n+1,args[n]);return statement;},keys);
    Number key=keys.getKey(); if(key==null)throw new IllegalStateException("Database did not return the inserted row id"); return key.longValue();
  }
  @GetMapping("/auth/me") Map<String,Object> me() { return one("SELECT id,username,role,vendor_id FROM app_users WHERE username=?",currentUser()); }
  @GetMapping("/users") @PreAuthorize("hasRole('ADMIN')") List<Map<String,Object>> users() { return many("SELECT id,username,role,vendor_id,enabled,created_at FROM app_users ORDER BY username"); }
  @PostMapping("/users") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> addUser(@Valid @RequestBody UserInput i) { if("VENDOR".equals(i.role())&&(i.vendorId()==null||db.queryForObject("SELECT COUNT(*) FROM vendors WHERE id=? AND active=TRUE",Integer.class,i.vendorId())==0)) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Vendor users must be linked to an active vendor"); if(!"VENDOR".equals(i.role())&&i.vendorId()!=null) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only vendor users can be linked to a vendor"); long id; try { id=insertId("INSERT INTO app_users(username,password_hash,role,vendor_id) VALUES(?,?,?,?)",i.username(),encoder.encode(i.password()),i.role(),i.vendorId()); } catch(DataIntegrityViolationException e) { throw new ResponseStatusException(HttpStatus.CONFLICT,"Username already exists"); } return one("SELECT id,username,role,vendor_id,enabled,created_at FROM app_users WHERE id=?",id); }
  @GetMapping("/dashboard") Map<String,Object> dashboard() {
    if("VENDOR".equals(currentRole())) {
      Long vendorId=currentVendorId();
      Map<String,Object> scoped=one("SELECT 1 vendors,NULL products,(SELECT COUNT(*) FROM purchase_orders WHERE vendor_id=?) orders,(SELECT COUNT(*) FROM purchase_orders WHERE vendor_id=? AND status IN ('PENDING','APPROVED','ORDERED')) open_orders,(SELECT COUNT(*) FROM purchase_orders WHERE vendor_id=? AND status='APPROVED') approved,(SELECT COUNT(*) FROM purchase_orders WHERE vendor_id=? AND status='RECEIVED') received,NULL low_stock",vendorId,vendorId,vendorId,vendorId);
      scoped.put("statusDistribution",many("SELECT status,COUNT(*) count FROM purchase_orders WHERE vendor_id=? GROUP BY status ORDER BY status",vendorId));
      scoped.put("recentOrders",many("SELECT p.id,p.po_number,p.status,p.subtotal,p.created_at,v.name vendor_name FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id WHERE p.vendor_id=? ORDER BY p.created_at DESC LIMIT 8",vendorId));
      scoped.put("lowStockItems",List.of()); scoped.put("vendorView",true); return scoped;
    }
    Map<String,Object> counts=one("SELECT (SELECT COUNT(*) FROM vendors WHERE active=TRUE) vendors,(SELECT COUNT(*) FROM products WHERE active=TRUE) products,(SELECT COUNT(*) FROM purchase_orders) orders,(SELECT COUNT(*) FROM purchase_orders WHERE status IN ('PENDING','APPROVED','ORDERED')) open_orders,(SELECT COUNT(*) FROM purchase_orders WHERE status='APPROVED') approved,(SELECT COUNT(*) FROM purchase_orders WHERE status='RECEIVED') received,(SELECT COUNT(*) FROM products WHERE active=TRUE AND stock_quantity<=reorder_threshold) low_stock");
    counts.put("statusDistribution",many("SELECT status,COUNT(*) count FROM purchase_orders GROUP BY status ORDER BY status")); counts.put("recentOrders",many("SELECT p.id,p.po_number,p.status,p.subtotal,p.created_at,v.name vendor_name FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id ORDER BY p.created_at DESC LIMIT 8"));
    counts.put("lowStockItems",many("SELECT id,sku,name,stock_quantity,reorder_threshold FROM products WHERE active=TRUE AND stock_quantity<=reorder_threshold ORDER BY stock_quantity LIMIT 8")); return counts;
  }
  @GetMapping("/vendors") List<Map<String,Object>> vendors(@RequestParam(defaultValue="") String search) { if("VENDOR".equals(currentRole())) return many("SELECT v.*, (SELECT COUNT(*) FROM purchase_orders p WHERE p.vendor_id=v.id) order_count FROM vendors v WHERE v.active=TRUE AND v.id=?",currentVendorId()); return many("SELECT v.*, (SELECT COUNT(*) FROM purchase_orders p WHERE p.vendor_id=v.id) order_count FROM vendors v WHERE v.active=TRUE AND (LOWER(v.name) LIKE LOWER(?) OR LOWER(v.email) LIKE LOWER(?)) ORDER BY v.name", "%"+search+"%", "%"+search+"%"); }
  @GetMapping("/vendors/{id}") Map<String,Object> vendor(@PathVariable long id) { if("VENDOR".equals(currentRole())&&!Objects.equals(currentVendorId(),id)) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Vendor users can only view their own organization"); Map<String,Object> v=one("SELECT * FROM vendors WHERE id=? AND active=TRUE",id); v.put("orders",many("SELECT id,po_number,status,subtotal,created_at FROM purchase_orders WHERE vendor_id=? ORDER BY created_at DESC",id)); return v; }
  @PostMapping("/vendors") @PreAuthorize("hasAnyRole('ADMIN','PURCHASE_MANAGER')") @Transactional Map<String,Object> addVendor(@Valid @RequestBody VendorInput i) { long id; try { id=insertId("INSERT INTO vendors(name,email,phone,address) VALUES(?,?,?,?)",i.name(),i.email(),i.phone(),i.address()); } catch(DataIntegrityViolationException e) { throw new ResponseStatusException(HttpStatus.CONFLICT,"A vendor with this email already exists"); } return one("SELECT * FROM vendors WHERE id=?",id); }
  @PutMapping("/vendors/{id}") @PreAuthorize("hasAnyRole('ADMIN','PURCHASE_MANAGER')") Map<String,Object> updateVendor(@PathVariable long id,@Valid @RequestBody VendorInput i) { db.update("UPDATE vendors SET name=?,email=?,phone=?,address=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND active=TRUE",i.name(),i.email(),i.phone(),i.address(),id); return one("SELECT * FROM vendors WHERE id=?",id); }
  @DeleteMapping("/vendors/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void deactivateVendor(@PathVariable long id) { db.update("UPDATE vendors SET active=FALSE,updated_at=CURRENT_TIMESTAMP WHERE id=?",id); }
  @GetMapping("/products") List<Map<String,Object>> products(@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="") String category,@RequestParam(defaultValue="false") boolean lowStock) { return many("SELECT * FROM products WHERE active=TRUE AND (LOWER(name) LIKE LOWER(?) OR LOWER(sku) LIKE LOWER(?)) AND (?='' OR category=?) AND (?=FALSE OR stock_quantity<=reorder_threshold) ORDER BY name", "%"+search+"%","%"+search+"%",category,category,lowStock); }
  @GetMapping("/products/{id}") Map<String,Object> product(@PathVariable long id) { return one("SELECT * FROM products WHERE id=?",id); }
  @PostMapping("/products") @PreAuthorize("hasAnyRole('ADMIN','INVENTORY_MANAGER')") @Transactional Map<String,Object> addProduct(@Valid @RequestBody ProductInput i) { long id; try { id=insertId("INSERT INTO products(sku,name,description,category,unit_price,stock_quantity,reorder_threshold) VALUES(?,?,?,?,?,?,?)",i.sku(),i.name(),i.description(),i.category(),i.unitPrice(),i.stockQuantity(),i.reorderThreshold()); } catch(DataIntegrityViolationException e) { throw new ResponseStatusException(HttpStatus.CONFLICT,"SKU already exists"); } Map<String,Object> created=one("SELECT * FROM products WHERE id=?",id); if(i.stockQuantity()>0) db.update("INSERT INTO inventory_transactions(product_id,user_id,transaction_type,quantity_change,note) VALUES(?,?,'INITIAL_STOCK',?,'Opening stock')",id,currentId(),i.stockQuantity()); return created; }
  @PutMapping("/products/{id}") @PreAuthorize("hasAnyRole('ADMIN','INVENTORY_MANAGER')") Map<String,Object> updateProduct(@PathVariable long id,@Valid @RequestBody ProductInput i) { db.update("UPDATE products SET sku=?,name=?,description=?,category=?,unit_price=?,reorder_threshold=? WHERE id=?",i.sku(),i.name(),i.description(),i.category(),i.unitPrice(),i.reorderThreshold(),id); return one("SELECT * FROM products WHERE id=?",id); }
  @DeleteMapping("/products/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void deactivateProduct(@PathVariable long id) { db.update("UPDATE products SET active=FALSE WHERE id=?",id); }
  @GetMapping("/orders") List<Map<String,Object>> orders(@RequestParam(required=false) String status,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size) { int safeSize=Math.max(1,Math.min(size,100)),offset=Math.max(0,page)*safeSize; String match="%"+search+"%"; return many("SELECT p.*,v.name vendor_name FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id WHERE (? IS NULL OR p.status=?) AND (p.po_number LIKE ? OR v.name LIKE ?) AND (? <> 'VENDOR' OR p.vendor_id=(SELECT vendor_id FROM app_users WHERE username=?)) ORDER BY p.created_at DESC LIMIT ? OFFSET ?",status,status,match,match,currentRole(),currentUser(),safeSize,offset); }
  @GetMapping("/orders/{id}") Map<String,Object> order(@PathVariable long id) { Map<String,Object> p=one("SELECT p.*,v.name vendor_name,v.email vendor_email FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id WHERE p.id=?",id); if("VENDOR".equals(currentRole())&&!Objects.equals(currentVendorId(),((Number)p.get("vendor_id")).longValue())) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Vendor users can only view their organization's orders"); p.put("items",many("SELECT i.*,x.sku,x.name product_name,i.quantity*i.unit_price line_total FROM purchase_order_items i JOIN products x ON x.id=i.product_id WHERE i.purchase_order_id=?",id)); return p; }
  @PostMapping("/orders") @PreAuthorize("hasAnyRole('ADMIN','PURCHASE_MANAGER')") @Transactional Map<String,Object> createOrder(@Valid @RequestBody OrderInput i) { if(db.queryForObject("SELECT COUNT(*) FROM vendors WHERE id=? AND active=TRUE",Integer.class,i.vendorId())==0) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Vendor not found"); String number="PO-"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(); long id=insertId("INSERT INTO purchase_orders(po_number,vendor_id,status,notes,created_by) VALUES(?,?,'PENDING',?,?)",number,i.vendorId(),i.notes(),currentId()); BigDecimal total=BigDecimal.ZERO; for(LineInput line:i.items()){ Map<String,Object> product=one("SELECT unit_price,active FROM products WHERE id=?",line.productId()); if(!Boolean.TRUE.equals(product.get("active"))) throw new ResponseStatusException(HttpStatus.CONFLICT,"Product is inactive"); BigDecimal price=(BigDecimal)product.get("unit_price"); db.update("INSERT INTO purchase_order_items(purchase_order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)",id,line.productId(),line.quantity(),price); total=total.add(price.multiply(BigDecimal.valueOf(line.quantity()))); } db.update("UPDATE purchase_orders SET subtotal=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",total,id); return order(id); }
  private void enforceTransitionRole(String next) {
    String role=db.queryForObject("SELECT role FROM app_users WHERE username=?",String.class,currentUser());
    boolean allowed="RECEIVED".equals(next) ? role.equals("ADMIN")||role.equals("INVENTORY_MANAGER") : role.equals("ADMIN")||role.equals("PURCHASE_MANAGER");
    if(!allowed) throw new AccessDeniedException("Your role cannot perform this purchase order transition");
  }  @PatchMapping("/orders/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','PURCHASE_MANAGER','INVENTORY_MANAGER')") @Transactional Map<String,Object> changeStatus(@PathVariable long id,@RequestBody Map<String,String> input) { String next=input.get("status"); Map<String,Object> current=one("SELECT status FROM purchase_orders WHERE id=? FOR UPDATE",id); String previous=(String)current.get("status"); enforceTransitionRole(next); if(!OrderWorkflow.canTransition(previous,next)) throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid transition: "+previous+" to "+next); if("RECEIVED".equals(next)){ List<Map<String,Object>> items=many("SELECT product_id,quantity FROM purchase_order_items WHERE purchase_order_id=?",id); for(Map<String,Object> item:items){ long productId=((Number)item.get("product_id")).longValue(); int qty=((Number)item.get("quantity")).intValue(); db.update("UPDATE products SET stock_quantity=stock_quantity+? WHERE id=?",qty,productId); db.update("INSERT INTO inventory_transactions(product_id,user_id,transaction_type,quantity_change,reference,note) VALUES(?,?,'PURCHASE_RECEIPT',?,?,?)",productId,currentId(),qty,one("SELECT po_number FROM purchase_orders WHERE id=?",id).get("po_number"),"Received purchase order"); }} db.update("UPDATE purchase_orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",next,id); return order(id); }
  @PostMapping("/inventory/{productId}/adjust") @PreAuthorize("hasAnyRole('ADMIN','INVENTORY_MANAGER')") @Transactional Map<String,Object> adjust(@PathVariable long productId,@Valid @RequestBody Adjustment a){ Map<String,Object> p=one("SELECT stock_quantity FROM products WHERE id=? FOR UPDATE",productId); int current=((Number)p.get("stock_quantity")).intValue(); if(a.quantity()<current) throw new ResponseStatusException(HttpStatus.CONFLICT,"Adjustment would make stock negative"); db.update("UPDATE products SET stock_quantity=? WHERE id=?",a.quantity(),productId); db.update("INSERT INTO inventory_transactions(product_id,user_id,transaction_type,quantity_change,note) VALUES(?,?,'ADJUSTMENT',?,?)",productId,currentId(),a.quantity()-current,a.note()); return one("SELECT * FROM products WHERE id=?",productId); }
  @GetMapping("/inventory/transactions") @PreAuthorize("hasAnyRole('ADMIN','INVENTORY_MANAGER')") List<Map<String,Object>> transactions(@RequestParam(defaultValue="0") int page){return many("SELECT t.*,p.sku,p.name product_name,u.username FROM inventory_transactions t JOIN products p ON p.id=t.product_id JOIN app_users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 100 OFFSET ?",Math.max(0,page)*100);}
  @GetMapping("/reports/summary") Map<String,Object> report(){Map<String,Object> r=new HashMap<>();r.put("vendorPurchases",many("SELECT v.name vendor_name,COUNT(p.id) order_count,COALESCE(SUM(p.subtotal),0) total FROM vendors v LEFT JOIN purchase_orders p ON p.vendor_id=v.id GROUP BY v.id ORDER BY total DESC"));r.put("inventory",many("SELECT category,COUNT(*) product_count,SUM(stock_quantity) units, SUM(stock_quantity*unit_price) value FROM products WHERE active=TRUE GROUP BY category"));r.put("status",many("SELECT status,COUNT(*) count,COALESCE(SUM(subtotal),0) amount FROM purchase_orders GROUP BY status"));return r;}
  @GetMapping(value="/reports/orders.csv",produces="text/csv") String csv(){StringBuilder out=new StringBuilder("PO Number,Vendor,Status,Total,Created At\n");for(Map<String,Object> r:many("SELECT p.po_number,v.name,p.status,p.subtotal,p.created_at FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id ORDER BY p.created_at DESC")){out.append('"').append(r.get("po_number")).append("\",\"").append(String.valueOf(r.get("name")).replace("\"","\"\"")).append("\",").append(r.get("status")).append(',').append(r.get("subtotal")).append(',').append(r.get("created_at")).append('\n');}return out.toString();}
  @GetMapping("/alerts") Map<String,Object> alerts(){return Map.of("lowStock",many("SELECT id,sku,name,stock_quantity,reorder_threshold FROM products WHERE active=TRUE AND stock_quantity<=reorder_threshold ORDER BY stock_quantity"),"pendingApproval",many("SELECT p.id,p.po_number,v.name vendor_name,p.created_at FROM purchase_orders p JOIN vendors v ON v.id=p.vendor_id WHERE p.status='PENDING' ORDER BY p.created_at"));}
}



